Here's a C function that tokenizes a string by whitespace without modifying the input, along with a cleanup function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/**
 * Tokenizes a string by whitespace into an array of strings.
 * 
 * @param str Input string to tokenize
 * @return Array of strings (NULL-terminated) or NULL if allocation fails
 */
char **tokenize_string(const char *str) {
    if (!str) return NULL;

    // First pass: count tokens
    size_t token_count = 0;
    int in_token = 0;

    for (const char *p = str; *p; p++) {
        if (!isspace((unsigned char)*p)) {
            if (!in_token) {
                token_count++;
                in_token = 1;
            }
        } else {
            in_token = 0;
        }
    }

    if (token_count == 0) {
        // Return an array with just a NULL terminator
        char **result = malloc(sizeof(char *));
        if (!result) return NULL;
        result[0] = NULL;
        return result;
    }

    // Allocate array for token pointers (plus NULL terminator)
    char **tokens = malloc((token_count + 1) * sizeof(char *));
    if (!tokens) return NULL;

    // Second pass: extract tokens
    size_t token_index = 0;
    in_token = 0;
    const char *token_start = NULL;

    for (const char *p = str; *p; p++) {
        if (!isspace((unsigned char)*p)) {
            if (!in_token) {
                token_start = p;
                in_token = 1;
            }
        } else {
            if (in_token) {
                // Token ended - extract it
                size_t token_len = p - token_start;
                tokens[token_index] = malloc(token_len + 1);
                if (!tokens[token_index]) {
                    // Cleanup on allocation failure
                    free_tokens(tokens);
                    return NULL;
                }
                strncpy(tokens[token_index], token_start, token_len);
                tokens[token_index][token_len] = '\0';
                token_index++;
                in_token = 0;
            }
        }
    }

    // Handle last token if string doesn't end with whitespace
    if (in_token) {
        size_t token_len = strlen(token_start);
        tokens[token_index] = malloc(token_len + 1);
        if (!tokens[token_index]) {
            free_tokens(tokens);
            return NULL;
        }
        strncpy(tokens[token_index], token_start, token_len);
        tokens[token_index][token_len] = '\0';
        token_index++;
    }

    // NULL terminate the array
    tokens[token_index] = NULL;

    return tokens;
}

/**
 * Frees memory allocated by tokenize_string.
 * 
 * @param tokens Array of strings to free (as returned by tokenize_string)
 */
void free_tokens(char **tokens) {
    if (!tokens) return;

    // Free each individual token string
    for (size_t i = 0; tokens[i] != NULL; i++) {
        free(tokens[i]);
    }

    // Free the array itself
    free(tokens);
}

/**
 * Example usage
 */
int main() {
    const char *test_string = "  Hello   world!   This is   a test.  ";

    printf("Input: \"%s\"\n\n", test_string);

    char **tokens = tokenize_string(test_string);
    if (tokens) {
        printf("Tokens found:\n");
        for (size_t i = 0; tokens[i] != NULL; i++) {
            printf("  [%zu]: \"%s\"\n", i, tokens[i]);
        }

        // Clean up
        free_tokens(tokens);
    } else {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Test edge cases
    printf("\nEdge case tests:\n");

    // Empty string
    char **empty_tokens = tokenize_string("");
    printf("Empty string: ");
    if (empty_tokens[0] == NULL) {
        printf("0 tokens (correct)\n");
    }
    free_tokens(empty_tokens);

    // Whitespace only
    char **space_tokens = tokenize_string("   \t\n");
    printf("Whitespace only: ");
    if (space_tokens[0] == NULL) {
        printf("0 tokens (correct)\n");
    }
    free_tokens(space_tokens);

    // Single token
    char **single_tokens = tokenize_string("single");
    printf("Single token: ");
    if (single_tokens[0] != NULL && single_tokens[1] == NULL) {
        printf("\"%s\" (correct)\n", single_tokens[0]);
    }
    free_tokens(single_tokens);

    return 0;
}
```

Key features of this implementation:

1. **No modification of input**: The function takes a `const char *` and never modifies the original string.

2. **Two-pass approach**:
   - First pass counts tokens to allocate appropriate memory
   - Second pass extracts tokens using `strncpy` to copy substrings

3. **Memory safety**:
   - Proper error handling with cleanup on allocation failures
   - Each token is null-terminated
   - The token array itself is NULL-terminated

4. **Cleanup function**: `free_tokens()` properly frees all allocated memory

5. **Edge case handling**:
   - Empty strings
   - Whitespace-only strings
   - Leading/trailing whitespace
   - Multiple consecutive whitespace characters

6. **Uses standard library functions**:
   - `isspace()` for whitespace detection
   - `malloc()`, `free()`, `strncpy()`, `strlen()`

The function tokenizes by any whitespace character (space, tab, newline, etc.) and handles multiple consecutive whitespace characters as single delimiters.

Here's a C function that uses POSIX `mmap` for memory-mapped file access with an `fread` fallback. The implementation provides a unified interface through a struct-based abstraction:

```c
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <string.h>

typedef struct {
    void *data;           // Pointer to file contents
    size_t size;          // Size of the file
    int is_mmap;          // Flag: 1 = mmap'd, 0 = fread'd
    int fd;               // File descriptor (for mmap'd files)
} FileData;

// Unified interface for accessing file contents
FileData read_file(const char *filename) {
    FileData result = {NULL, 0, 0, -1};

    // Open file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return result;
    }

    // Get file size
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Failed to stat file");
        close(fd);
        return result;
    }
    result.size = sb.st_size;

    // Try memory mapping first
    void *data = mmap(NULL, result.size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data != MAP_FAILED) {
        result.data = data;
        result.is_mmap = 1;
        result.fd = fd;  // Keep fd open for munmap later
        return result;
    }

    // Fallback to fread if mmap fails
    data = malloc(result.size);
    if (data == NULL) {
        perror("Failed to allocate memory");
        close(fd);
        return result;
    }

    ssize_t bytes_read = read(fd, data, result.size);
    if (bytes_read == -1 || (size_t)bytes_read != result.size) {
        perror("Failed to read file");
        free(data);
        close(fd);
        return result;
    }

    result.data = data;
    result.is_mmap = 0;
    result.fd = fd;
    return result;
}

// Release resources
void free_file(FileData *fd) {
    if (fd == NULL) return;

    if (fd->is_mmap) {
        if (fd->data != NULL && fd->data != MAP_FAILED) {
            munmap(fd->data, fd->size);
        }
        if (fd->fd != -1) {
            close(fd->fd);
        }
    } else {
        free(fd->data);
        if (fd->fd != -1) {
            close(fd->fd);
        }
    }

    // Reset structure
    fd->data = NULL;
    fd->size = 0;
    fd->is_mmap = 0;
    fd->fd = -1;
}

// Example usage
int main() {
    FileData file = read_file("example.txt");
    if (file.data == NULL) {
        fprintf(stderr, "Failed to read file\n");
        return 1;
    }

    // Use the file contents
    printf("File size: %zu bytes\n", file.size);
    printf("Method used: %s\n", file.is_mmap ? "mmap" : "fread");

    // Access file contents (for demonstration, print first 100 characters or less)
    size_t print_size = file.size < 100 ? file.size : 100;
    printf("First %zu characters: ", print_size);
    fwrite(file.data, 1, print_size, stdout);
    printf("\n");

    // Clean up
    free_file(&file);
    return 0;
}
```

Key features of this implementation:

1. **Unified Interface**: 
   - `read_file()` attempts memory mapping first, falls back to `read()` (which can be easily changed to `fread()` if needed)
   - `free_file()` handles cleanup appropriately based on the method used

2. **Error Handling**:
   - Returns a struct with NULL data on failure
   - Properly cleans up resources on error paths
   - Uses MAP_FAILED check for mmap failures

3. **Resource Management**:
   - Keeps file descriptor open for mmap'd files (required for proper cleanup)
   - Properly frees memory or unmaps memory based on method used
   - Resets struct fields after cleanup

4. **Platform Considerations**:
   - Uses POSIX-compliant functions
   - Handles zero-sized files gracefully
   - Works with both small and large files

To use `fread` instead of `read()` in the fallback path, simply replace the `read()` call with:
```c
FILE *fp = fopen(filename, "rb");
if (fp == NULL) {
    perror("Failed to open file");
    free(data);
    close(fd);
    return result;
}
size_t bytes_read = fread(data, 1, result.size, fp);
fclose(fp);
// Then proceed with the rest of the function
```

The implementation ensures that the same API works regardless of whether memory mapping succeeded, making it transparent to the calling code.

Here's a clean, robust C function that greedily finds the longest vocabulary token matching the start of a text buffer. It returns the token's array index as the ID and the number of bytes consumed.

```c
#include <string.h>
#include <stddef.h>

/**
 * Greedily matches the longest token from `vocabulary` that is a prefix
 * of the first `buf_len` characters of `buffer`.
 *
 * @param buffer      The text buffer to scan (null-terminated if buf_len == 0).
 * @param vocabulary  Array of token strings (must not be NULL).
 * @param vocab_size  Number of tokens in the vocabulary.
 * @param buf_len     Number of characters from `buffer` to consider.
 *                    Pass 0 to use strlen(buffer).
 * @param out_token_id Output: index in `vocabulary` of the matched token.
 * @param out_length  Output: number of bytes consumed (match length).
 *
 * @return 0 on success, -1 if no vocabulary token matches the buffer start.
 *         Also returns -1 if input pointers are NULL.
 */
int greedy_token_match(const char* buffer,
                       const char* vocabulary[],
                       size_t vocab_size,
                       size_t buf_len,
                       int* out_token_id,
                       size_t* out_length)
{
    if (!buffer || !vocabulary || !out_token_id || !out_length)
        return -1;

    /* Determine how many bytes of buffer we actually look at */
    size_t limit = (buf_len == 0) ? strlen(buffer) : buf_len;
    if (limit == 0) {
        *out_token_id = -1;
        *out_length = 0;
        return -1;
    }

    size_t best_len = 0;
    int best_id = -1;

    for (size_t i = 0; i < vocab_size; ++i) {
        const char* token = vocabulary[i];
        if (!token) continue;

        size_t token_len = strlen(token);
        if (token_len == 0 || token_len > limit) continue;

        /* Check if token is a prefix of the buffer start */
        if (strncmp(buffer, token, token_len) == 0) {
            /* Greedily keep the longest match; on tie, keep the first one found */
            if (token_len > best_len) {
                best_len = token_len;
                best_id = (int)i;
            }
        }
    }

    if (best_id >= 0) {
        *out_token_id = best_id;
        *out_length = best_len;
        return 0;
    }

    *out_token_id = -1;
    *out_length = 0;
    return -1;
}
```

### Quick usage example
```c
#include <stdio.h>

int main(void) {
    const char* buf = "foobar";
    const char* vocab[] = {"f", "fo", "foo", "foobar", "bar"};
    size_t vsize = sizeof(vocab) / sizeof(vocab[0]);
    int id; size_t len;

    if (greedy_token_match(buf, vocab, vsize, 0, &id, &len) == 0)
        printf("Matched token #%d, consumed %zu bytes: \"%.*s\"\n",
               id, len, (int)len, buf);
    else
        printf("No match\n");

    return 0;
}
```
/* Output: Matched token #3, consumed 6 bytes: "foobar" */

### Notes
* Tie-breaking: if multiple tokens share the same maximum length, the first one encountered in the array wins.
* No match: `*out_token_id` is set to `-1` and `*out_length` to `0`; the function returns `-1`.
* Pass `buf_len` explicitly if your buffer isn't null-terminated or you want to limit the scan area.
* All standard C89/C99 compatible; only uses `<string.h>` and `<stddef.h>`.

Here's a C implementation for safe UTF-8 ↔ UTF-32 conversion with detailed comments:

```c
#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

// Error codes for UTF-8 decoding
typedef enum {
    UTF8_OK = 0,
    UTF8_ERR_INVALID_BYTE,        // Invalid start byte
    UTF8_ERR_UNEXPECTED_CONT,     // Unexpected continuation byte
    UTF8_ERR_UNTRUNCATED_SEQ,     // Sequence ends prematurely
    UTF8_ERR_INVALID_CODEPOINT,   // Surrogate half or > 0x10FFFF
    UTF8_ERR_OVERLONG,            // Overlong encoding
    UTF8_ERR_BUFFER_TOO_SMALL     // Output buffer too small
} UTF8Error;

/**
 * Decodes a single UTF-8 sequence to a UTF-32 codepoint
 * 
 * @param str        Input UTF-8 string
 * @param len        Length of input buffer in bytes
 * @param codepoint  Output: decoded UTF-32 codepoint
 * @param bytes_used Output: number of bytes consumed from input
 * @return           Error code (UTF8_OK on success)
 */
UTF8Error utf8_decode(const uint8_t *str, size_t len, 
                      uint32_t *codepoint, size_t *bytes_used)
{
    if (!str || !codepoint || !bytes_used || len == 0) {
        return UTF8_ERR_INVALID_BYTE;
    }

    *bytes_used = 0;
    *codepoint = 0;

    // Check first byte to determine sequence length
    uint8_t first = str[0];
    int expected_bytes;

    if (first <= 0x7F) {
        // ASCII (0xxxxxxx)
        *codepoint = first;
        *bytes_used = 1;
        return UTF8_OK;
    } 
    else if ((first & 0xE0) == 0xC0) {
        // 2-byte sequence (110xxxxx)
        expected_bytes = 2;
        *codepoint = first & 0x1F;
    } 
    else if ((first & 0xF0) == 0xE0) {
        // 3-byte sequence (1110xxxx)
        expected_bytes = 3;
        *codepoint = first & 0x0F;
    } 
    else if ((first & 0xF8) == 0xF0) {
        // 4-byte sequence (11110xxx)
        expected_bytes = 4;
        *codepoint = first & 0x07;
    } 
    else {
        // Invalid start byte (10xxxxxx or 11111xxx)
        return UTF8_ERR_INVALID_BYTE;
    }

    // Check for overlong encoding
    if (expected_bytes == 2 && *codepoint < 0x02) {
        return UTF8_ERR_OVERLONG;
    }
    else if (expected_bytes == 3 && *codepoint < 0x08) {
        return UTF8_ERR_OVERLONG;
    }
    else if (expected_bytes == 4 && *codepoint < 0x10) {
        return UTF8_ERR_OVERLONG;
    }

    // Check we have enough bytes
    if ((size_t)expected_bytes > len) {
        return UTF8_ERR_UNTRUNCATED_SEQ;
    }

    // Process continuation bytes
    for (int i = 1; i < expected_bytes; i++) {
        uint8_t byte = str[i];

        // Check continuation byte format (10xxxxxx)
        if ((byte & 0xC0) != 0x80) {
            *bytes_used = i; // Consume valid prefix
            return UTF8_ERR_UNEXPECTED_CONT;
        }

        *codepoint = (*codepoint << 6) | (byte & 0x3F);
    }

    *bytes_used = expected_bytes;

    // Validate codepoint ranges
    if (*codepoint > 0x10FFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    // Check for surrogate halves (U+D800 to U+DFFF)
    if (*codepoint >= 0xD800 && *codepoint <= 0xDFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    // Check for overlong encodings (canonical form)
    if (expected_bytes == 2 && *codepoint < 0x80) {
        return UTF8_ERR_OVERLONG;
    }
    else if (expected_bytes == 3 && *codepoint < 0x800) {
        return UTF8_ERR_OVERLONG;
    }
    else if (expected_bytes == 4 && *codepoint < 0x10000) {
        return UTF8_ERR_OVERLONG;
    }

    return UTF8_OK;
}

/**
 * Encodes a UTF-32 codepoint to UTF-8
 * 
 * @param codepoint  Input UTF-32 codepoint
 * @param buffer     Output buffer (must be at least 4 bytes)
 * @param buffer_size Size of output buffer
 * @param bytes_written Output: number of bytes written
 * @return           Error code (UTF8_OK on success)
 */
UTF8Error utf8_encode(uint32_t codepoint, uint8_t *buffer, 
                      size_t buffer_size, size_t *bytes_written)
{
    if (!buffer || !bytes_written || buffer_size == 0) {
        return UTF8_ERR_BUFFER_TOO_SMALL;
    }

    *bytes_written = 0;

    // Check for invalid codepoints
    if (codepoint > 0x10FFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    // Check for surrogate halves
    if (codepoint >= 0xD800 && codepoint <= 0xDFFF) {
        return UTF8_ERR_INVALID_CODEPOINT;
    }

    // Determine number of bytes needed
    int bytes_needed;
    uint8_t first_byte_mask;

    if (codepoint <= 0x7F) {
        bytes_needed = 1;
        first_byte_mask = 0x00; // 0xxxxxxx
    }
    else if (codepoint <= 0x7FF) {
        bytes_needed = 2;
        first_byte_mask = 0xC0; // 110xxxxx
    }
    else if (codepoint <= 0xFFFF) {
        bytes_needed = 3;
        first_byte_mask = 0xE0; // 1110xxxx
    }
    else { // codepoint <= 0x10FFFF
        bytes_needed = 4;
        first_byte_mask = 0xF0; // 11110xxx
    }

    // Check buffer size
    if ((size_t)bytes_needed > buffer_size) {
        return UTF8_ERR_BUFFER_TOO_SMALL;
    }

    // Write continuation bytes first (backwards)
    int shift = (bytes_needed - 1) * 6;

    for (int i = bytes_needed - 1; i > 0; i--) {
        buffer[i] = 0x80 | ((codepoint >> shift) & 0x3F);
        shift -= 6;
    }

    // Write first byte
    buffer[0] = first_byte_mask | (codepoint >> shift);

    *bytes_written = bytes_needed;
    return UTF8_OK;
}

/**
 * Helper function to get human-readable error message
 */
const char* utf8_error_string(UTF8Error error) {
    switch (error) {
        case UTF8_OK:                 return "Success";
        case UTF8_ERR_INVALID_BYTE:   return "Invalid start byte";
        case UTF8_ERR_UNEXPECTED_CONT:return "Unexpected continuation byte";
        case UTF8_ERR_UNTRUNCATED_SEQ:return "Untruncated sequence";
        case UTF8_ERR_INVALID_CODEPOINT:return "Invalid codepoint (surrogate or > 0x10FFFF)";
        case UTF8_ERR_OVERLONG:       return "Overlong encoding";
        case UTF8_ERR_BUFFER_TOO_SMALL:return "Buffer too small";
        default:                      return "Unknown error";
    }
}

// Example usage
#ifdef EXAMPLE_USAGE
#include <stdio.h>

void print_utf8_sequence(const uint8_t *str, size_t len) {
    size_t pos = 0;
    uint32_t codepoint;
    size_t bytes_used;
    UTF8Error err;

    printf("Decoding UTF-8 sequence:\n");

    while (pos < len) {
        err = utf8_decode(str + pos, len - pos, &codepoint, &bytes_used);

        if (err != UTF8_OK) {
            printf("  Error at byte %zu: %s\n", pos, utf8_error_string(err));
            // Skip invalid byte
            pos++;
        } else {
            printf("  U+%04X (%zu bytes)\n", codepoint, bytes_used);
            pos += bytes_used;
        }
    }
}

void test_utf32_to_utf8(uint32_t codepoint) {
    uint8_t buffer[4];
    size_t bytes_written;

    printf("Encoding U+%04X: ", codepoint);

    UTF8Error err = utf8_encode(codepoint, buffer, sizeof(buffer), &bytes_written);

    if (err != UTF8_OK) {
        printf("Error - %s\n", utf8_error_string(err));
        return;
    }

    printf("UTF-8: ");
    for (size_t i = 0; i < bytes_written; i++) {
        printf("%02X ", buffer[i]);
    }
    printf("\n");
}

int main() {
    // Example test cases
    printf("=== UTF-8 Decoding ===\n");

    // Valid sequences
    const uint8_t valid1[] = {0x48, 0x65, 0x6C, 0x6C, 0x6F}; // "Hello"
    print_utf8_sequence(valid1, sizeof(valid1));

    const uint8_t valid2[] = {0xC3, 0xA9}; // é (U+00E9)
    print_utf8_sequence(valid2, sizeof(valid2));

    const uint8_t valid3[] = {0xE4, 0xBD, 0xA0}; // 你 (U+4F60)
    print_utf8_sequence(valid3, sizeof(valid3));

    const uint8_t valid4[] = {0xF0, 0x9F, 0x91, 0x80}; // 👀 (U+1F440)
    print_utf8_sequence(valid4, sizeof(valid4));

    // Invalid sequences
    printf("\n=== Invalid Sequences ===\n");
    const uint8_t invalid1[] = {0xFE}; // Invalid start byte
    print_utf8_sequence(invalid1, sizeof(invalid1));

    const uint8_t invalid2[] = {0xC0, 0x80}; // Overlong encoding (U+0000)
    print_utf8_sequence(invalid2, sizeof(invalid2));

    const uint8_t invalid3[] = {0xED, 0xA0, 0x80}; // Surrogate (U+D800)
    print_utf8_sequence(invalid3, sizeof(invalid3));

    printf("\n=== UTF-32 to UTF-8 Encoding ===\n");
    test_utf32_to_utf8(0x41);    // A
    test_utf32_to_utf8(0xE9);   // é
    test_utf32_to_utf8(0x4F60); // 你
    test_utf32_to_utf8(0x1F440); // 👀
    test_utf32_to_utf8(0xD800); // Invalid surrogate

    return 0;
}
#endif
```

## Key Features:

1. **Safe decoding with error handling:**
   - Returns specific error codes for different types of invalid sequences
   - Consumes only valid bytes, allowing recovery from errors
   - Detects all common UTF-8 errors: invalid start bytes, unexpected continuation bytes, overlong encodings, and surrogate halves

2. **Complete encoding with validation:**
   - Produces minimal (canonical) UTF-8 encodings
   - Rejects invalid codepoints (surrogates, > 0x10FFFF)
   - Ensures buffer doesn't overflow

3. **Comprehensive validation:**
   - Checks all Unicode rules per RFC 3629
   - Detects overlong encodings (same codepoint encoded with more bytes than necessary)
   - Validates codepoint ranges

4. **Practical API:**
   - Returns detailed error information
   - Tracks bytes consumed/written for streaming processing
   - Helper function for human-readable error messages

## Example Usage Patterns:

**Decoding stream:**
```c
const uint8_t *data = /* some UTF-8 data */;
size_t len = /* length */;
size_t pos = 0;

while (pos < len) {
    uint32_t codepoint;
    size_t bytes_used;

    UTF8Error err = utf8_decode(data + pos, len - pos, &codepoint, &bytes_used);

    if (err == UTF8_OK) {
        // Process valid codepoint
        process_codepoint(codepoint);
        pos += bytes_used;
    } else {
        // Handle error, skip invalid byte
        handle_error(err, pos);
        pos++; // Skip invalid byte
    }
}
```

