The implementation handles all edge cases safely while providing clear error feedback for debugging invalid sequences.

# C Functions for Reading Little-Endian uint64 and Varint

```c
#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/**
 * read_le_uint64 - Read a little-endian 64-bit unsigned integer.
 *
 * @buf:      pointer to the byte buffer
 * @buf_len:  total number of bytes available in the buffer
 * @cursor:   [in/out] current read offset; advanced by 8 on success
 * @out:      [out] receives the decoded value
 *
 * Returns true on success, false if fewer than 8 bytes remain.
 */
static inline bool read_le_uint64(const uint8_t *buf, size_t buf_len,
                                  size_t *cursor, uint64_t *out)
{
    if (*cursor + 8 > buf_len)
        return false;

    const uint8_t *p = buf + *cursor;

    *out = (uint64_t)p[0]
         | ((uint64_t)p[1] <<  8)
         | ((uint64_t)p[2] << 16)
         | ((uint64_t)p[3] << 24)
         | ((uint64_t)p[4] << 32)
         | ((uint64_t)p[5] << 40)
         | ((uint64_t)p[6] << 48)
         | ((uint64_t)p[7] << 56);

    *cursor += 8;
    return true;
}

/**
 * read_varint - Read a little-endian Base-128 (LEB128) variable-length integer.
 *
 * Each byte carries 7 payload bits in its low bits and one continuation
 * bit in its high bit (MSB).  While the MSB is set, more bytes follow.
 * A maximum of 10 bytes are consumed (sufficient for a full uint64).
 *
 * @buf:      pointer to the byte buffer
 * @buf_len:  total number of bytes available in the buffer
 * @cursor:   [in/out] current read offset; advanced on success
 * @out:      [out] receives the decoded value
 *
 * Returns true on success, false if the buffer is exhausted before the
 * varint terminates or if it would require more than 10 bytes.
 */
static inline bool read_varint(const uint8_t *buf, size_t buf_len,
                               size_t *cursor, uint64_t *out)
{
    uint64_t result = 0;
    int      shift  = 0;

    for (int i = 0; i < 10; ++i) {
        if (*cursor >= buf_len)          /* bounds check before read */
            return false;

        uint8_t byte = buf[*cursor];
        (*cursor)++;

        result |= (uint64_t)(byte & 0x7F) << shift;

        if ((byte & 0x80) == 0) {        /* MSB clear → last byte */
            *out = result;
            return true;
        }

        shift += 7;
    }

    return false;                        /* varint > 10 bytes */
}
```

