    uint64_t val;

    if (read_le_uint64(buf, sizeof(buf), &cursor, &val))
        printf("uint64:  0x%016llX  (cursor=%zu)\n",
               (unsigned long long)val, cursor);
    else
        printf("Failed to read uint64\n");

    if (read_varint(buf, sizeof(buf), &cursor, &val))
        printf("varint:  %llu       (cursor=%zu)\n",
               (unsigned long long)val, cursor);
    else
        printf("Failed to read varint\n");

    return 0;
}
