#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef enum {
    TOKEN_LBRACE,     // {
    TOKEN_RBRACE,     // }
    TOKEN_LBRACKET,   // [
    TOKEN_RBRACKET,   // ]
    TOKEN_COLON,      // :
    TOKEN_COMMA,      // ,
    TOKEN_STRING,     // "..."
    TOKEN_NUMBER,     // 123, 12.3, 1.23e4
    TOKEN_TRUE,       // true
    TOKEN_FALSE,      // false
    TOKEN_NULL,       // null
    TOKEN_END,        // end of input
    TOKEN_ERROR       // invalid token
} TokenType;

typedef struct {
    TokenType type;
    size_t start;
    size_t length;
} Token;

typedef struct {
    Token* tokens;
    size_t count;
    size_t capacity;
} Tokenizer;

// Initialize tokenizer
void tokenizer_init(Tokenizer* tokenizer) {
    tokenizer->tokens = NULL;
    tokenizer->count = 0;
    tokenizer->capacity = 0;
}

// Add token to the tokenizer
void add_token(Tokenizer* tokenizer, TokenType type, size_t start, size_t length) {
    if (tokenizer->count >= tokenizer->capacity) {
        tokenizer->capacity = tokenizer->capacity ? tokenizer->capacity * 2 : 16;
        tokenizer->tokens = realloc(tokenizer->tokens, tokenizer->capacity * sizeof(Token));
    }

    Token token = {type, start, length};
    tokenizer->tokens[tokenizer->count++] = token;
}

// Skip whitespace
size_t skip_whitespace(const char* json, size_t pos) {
    while (json[pos] && (json[pos] == ' ' || json[pos] == '\t' || 
           json[pos] == '\n' || json[pos] == '\r')) {
        pos++;
    }
    return pos;
}

// Parse string token
size_t parse_string(const char* json, size_t start, Tokenizer* tokenizer) {
    size_t pos = start + 1; // Skip opening quote

    while (json[pos] != '\0') {
        if (json[pos] == '\\') {
            pos += 2; // Skip escaped character
        } else if (json[pos] == '"') {
            // Found closing quote
            size_t length = pos - start + 1;
            add_token(tokenizer, TOKEN_STRING, start, length);
            return pos + 1;
        } else {
            pos++;
        }
    }

    // If we reach here, string is not terminated
    add_token(tokenizer, TOKEN_ERROR, start, pos - start);
    return pos;
}

// Parse number token
size_t parse_number(const char* json, size_t start, Tokenizer* tokenizer) {
    size_t pos = start;

    // Optional minus
    if (json[pos] == '-') {
        pos++;
    }

    // Integer part (0 or positive integer)
    if (json[pos] == '0') {
        pos++;
    } else if (isdigit(json[pos])) {
        while (isdigit(json[pos])) {
            pos++;
        }
    } else {
        add_token(tokenizer, TOKEN_ERROR, start, pos - start);
        return pos;
    }

    // Optional fractional part
    if (json[pos] == '.') {
        pos++;
        if (!isdigit(json[pos])) {
            add_token(tokenizer, TOKEN_ERROR, start, pos - start);
            return pos;
        }
        while (isdigit(json[pos])) {
            pos++;
        }
    }

    // Optional exponent part
    if (json[pos] == 'e' || json[pos] == 'E') {
        pos++;
        if (json[pos] == '+' || json[pos] == '-') {
            pos++;
        }
        if (!isdigit(json[pos])) {
            add_token(tokenizer, TOKEN_ERROR, start, pos - start);
            return pos;
        }
        while (isdigit(json[pos])) {
            pos++;
        }
    }

    size_t length = pos - start;
    add_token(tokenizer, TOKEN_NUMBER, start, length);
    return pos;
}

// Parse literal token (true, false, null)
size_t parse_literal(const char* json, size_t start, Tokenizer* tokenizer) {
    const char* literals[] = {"true", "false", "null"};
    TokenType types[] = {TOKEN_TRUE, TOKEN_FALSE, TOKEN_NULL};

    for (int i = 0; i < 3; i++) {
        size_t len = strlen(literals[i]);
        if (strncmp(json + start, literals[i], len) == 0) {
            add_token(tokenizer, types[i], start, len);
            return start + len;
        }
    }

    add_token(tokenizer, TOKEN_ERROR, start, 1);
    return start + 1;
}

// Main tokenize function
Tokenizer tokenize(const char* json) {
    Tokenizer tokenizer;
    tokenizer_init(&tokenizer);

    size_t pos = 0;

    while (json[pos] != '\0') {
        pos = skip_whitespace(json, pos);

        if (json[pos] == '\0') {
            break;
        }

        switch (json[pos]) {
            case '{':
                add_token(&tokenizer, TOKEN_LBRACE, pos, 1);
                pos++;
                break;
            case '}':
                add_token(&tokenizer, TOKEN_RBRACE, pos, 1);
                pos++;
                break;
            case '[':
                add_token(&tokenizer, TOKEN_LBRACKET, pos, 1);
                pos++;
                break;
            case ']':
                add_token(&tokenizer, TOKEN_RBRACKET, pos, 1);
                pos++;
                break;
            case ':':
                add_token(&tokenizer, TOKEN_COLON, pos, 1);
                pos++;
                break;
            case ',':
                add_token(&tokenizer, TOKEN_COMMA, pos, 1);
                pos++;
                break;
            case '"':
                pos = parse_string(json, pos, &tokenizer);
                break;
            case 't':
            case 'f':
            case 'n':
                pos = parse_literal(json, pos, &tokenizer);
                break;
            default:
                if (isdigit(json[pos]) || json[pos] == '-') {
                    pos = parse_number(json, pos, &tokenizer);
                } else {
                    add_token(&tokenizer, TOKEN_ERROR, pos, 1);
                    pos++;
                }
                break;
        }
    }

    add_token(&tokenizer, TOKEN_END, pos, 0);
    return tokenizer;
}

// Free tokenizer resources
void tokenizer_free(Tokenizer* tokenizer) {
    free(tokenizer->tokens);
    tokenizer->tokens = NULL;
    tokenizer->count = 0;
    tokenizer->capacity = 0;
}

// Helper function to get token type name
const char* token_type_name(TokenType type) {
    switch (type) {
        case TOKEN_LBRACE: return "LBRACE";
        case TOKEN_RBRACE: return "RBRACE";
        case TOKEN_LBRACKET: return "LBRACKET";
        case TOKEN_RBRACKET: return "RBRACKET";
        case TOKEN_COLON: return "COLON";
        case TOKEN_COMMA: return "COMMA";
        case TOKEN_STRING: return "STRING";
        case TOKEN_NUMBER: return "NUMBER";
        case TOKEN_TRUE: return "TRUE";
        case TOKEN_FALSE: return "FALSE";
        case TOKEN_NULL: return "NULL";
        case TOKEN_END: return "END";
        case TOKEN_ERROR: return "ERROR";
        default: return "UNKNOWN";
    }
}

// Example usage
int main() {
    const char* json = "{\"name\": \"John\", \"age\": 30, \"active\": true, \"address\": null}";

    printf("JSON: %s\n\n", json);

    Tokenizer tokenizer = tokenize(json);

    printf("Tokens:\n");
    for (size_t i = 0; i < tokenizer.count; i++) {
        Token token = tokenizer.tokens[i];
        printf("%2zu: %-10s (start=%2zu, length=%2zu) -> \"",
               i, token_type_name(token.type), token.start, token.length);

        // Print the actual token content (for demonstration)
        for (size_t j = token.start; j < token.start + token.length; j++) {
            putchar(json[j]);
        }
        printf("\"\n");
    }

    tokenizer_free(&tokenizer);
    return 0;
}
```

