#include <stdio.h>

/**
 * Swaps the VALUES that two int* pointers point to
 * (swaps the integers in memory)
 */
void swap_int_values(int **pp1, int **pp2) {
    if (pp1 == NULL || pp2 == NULL || *pp1 == NULL || *pp2 == NULL) {
        return;  // Safety check
    }

    // Create temporary to hold the value
    int temp = **pp1;

    // Swap the values in memory
    **pp1 = **pp2;
    **pp2 = temp;
}

/**
 * Swaps the POINTERS themselves (the memory addresses stored in the int**)
 * (swaps which addresses the pointers point to)
 */
void swap_int_pointers(int ***ppp1, int ***ppp2) {
    if (ppp1 == NULL || ppp2 == NULL) {
        return;  // Safety check
    }

    // Create temporary to hold the pointer
    int *temp = **ppp1;

    // Swap the pointers themselves
    **ppp1 = **ppp2;
    **ppp2 = temp;
}

// Helper function to print the state
void print_state(const char *label, 
                 int *p1, int *p2, 
                 int **pp1, int **pp2) {
    printf("%s:\n", label);
    printf("  p1 = %p, *p1 = %d\n", (void*)p1, *p1);
    printf("  p2 = %p, *p2 = %d\n", (void*)p2, *p2);
    printf("  pp1 points to p1? %s\n", 
           *pp1 == p1 ? "yes" : "no");
    printf("  pp2 points to p2? %s\n", 
           *pp2 == p2 ? "yes" : "no");
}

int main() {
    // Setup
    int val1 = 10;
    int val2 = 20;
    int *p1 = &val1;
    int *p2 = &val2;
    int **pp1 = &p1;  // pp1 points to p1
    int **pp2 = &p2;  // pp2 points to p2

    // Show initial state
    printf("=== INITIAL STATE ===\n");
    print_state("Initial", p1, p2, pp1, pp2);

    // Demo 1: Swap VALUES (int* contents)
    printf("\n=== SWAPPING VALUES (swap_int_values) ===\n");
    swap_int_values(pp1, pp2);
    print_state("After value swap", p1, p2, pp1, pp2);

    // Reset to original
    val1 = 10; val2 = 20;
    p1 = &val1; p2 = &val2;
    pp1 = &p1; pp2 = &p2;

    // Demo 2: Swap POINTERS (int** pointers)
    printf("\n=== SWAPPING POINTERS (swap_int_pointers) ===\n");
    swap_int_pointers(&pp1, &pp2);
    print_state("After pointer swap", p1, p2, pp1, pp2);

    return 0;
}
